func (q *Queries) ListUnappliedPreviewEvents(ctx context.Context, n int32) ([]ListUnappliedPreviewEventsRow, error) {
	rows, err := q.db.Query(ctx, listUnappliedPreviewEvents, n)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListUnappliedPreviewEventsRow{}
	for rows.Next() {
		var i ListUnappliedPreviewEventsRow
		if err := rows.Scan(&i.ID, &i.PullRequestID, &i.ActorID); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const listUntrustedPreviewEnvironments = `-- name: ListUntrustedPreviewEnvironments :many
SELECT v.environment_id::uuid AS environment_id
FROM previews v JOIN projects p ON p.id = v.project_id
WHERE v.untrusted AND v.environment_id IS NOT NULL
  AND (v.project_id = $1::uuid OR p.org_id = $2::uuid)
`

type ListUntrustedPreviewEnvironmentsParams struct {
	ProjectID pgtype.UUID `json:"project_id"`
	OrgID     pgtype.UUID `json:"org_id"`
}

// Every untrusted preview's environment of a project, or of an org's
// projects: shared services never publish into them.
func (q *Queries) ListUntrustedPreviewEnvironments(ctx context.Context, arg ListUntrustedPreviewEnvironmentsParams) ([]pgtype.UUID, error) {
	rows, err := q.db.Query(ctx, listUntrustedPreviewEnvironments, arg.ProjectID, arg.OrgID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []pgtype.UUID{}
	for rows.Next() {
		var environment_id pgtype.UUID
		if err := rows.Scan(&environment_id); err != nil {
			return nil, err
		}
		items = append(items, environment_id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

