const updatePreview = `-- name: UpdatePreview :exec
UPDATE previews SET environment_id = $1, untrusted = $2, head_sha = $3,
       approved_sha = $4, approved_by = $5, approved_at = $6,
       state = $7, stopped_reason = $8, note = $9,
       updated_at = CASE WHEN (environment_id, untrusted, head_sha, approved_sha, approved_by, approved_at, state, stopped_reason, note)
                              IS DISTINCT FROM ($1::uuid, $2::boolean, $3::text,
                                                $4::text, $5::uuid, $6::timestamptz,
                                                $7::text, $8::text, $9::text)
                         THEN NOW() ELSE updated_at END
WHERE id = $10
`

type UpdatePreviewParams struct {
	EnvironmentID pgtype.UUID        `json:"environment_id"`
	Untrusted     bool               `json:"untrusted"`
	HeadSha       string             `json:"head_sha"`
	ApprovedSha   *string            `json:"approved_sha"`
	ApprovedBy    pgtype.UUID        `json:"approved_by"`
	ApprovedAt    pgtype.Timestamptz `json:"approved_at"`
	State         string             `json:"state"`
	StoppedReason *string            `json:"stopped_reason"`
	Note          string             `json:"note"`
	ID            pgtype.UUID        `json:"id"`
}

// updated_at moves only when something did: the reconcile saves a
// preview it found unchanged, as at every start.
func (q *Queries) UpdatePreview(ctx context.Context, arg UpdatePreviewParams) error {
	_, err := q.db.Exec(ctx, updatePreview,
		arg.EnvironmentID,
		arg.Untrusted,
		arg.HeadSha,
		arg.ApprovedSha,
		arg.ApprovedBy,
		arg.ApprovedAt,
		arg.State,
		arg.StoppedReason,
		arg.Note,
		arg.ID,
	)
	return err
}
